"""CI/CD scaffolding for deployment (FR-13): Git branch + Snowflake CLI or schemachange, never from the UI."""
from __future__ import annotations

WORKFLOW = """name: semlift-deploy
# Generated by SemanticLift. Deploys only reviewed + approved objects (migrations/ is written by `semlift deploy`).
on:
  pull_request:
    paths: ["migrations/**", "manifest.json"]
  push:
    branches: [main]
    paths: ["migrations/**", "manifest.json"]
  workflow_dispatch: {}

permissions:
  contents: read

jobs:
  validate:
    runs-on: ubuntu-latest
    env:
      HAS_SNOWFLAKE: ${{ secrets.SNOWFLAKE_ACCOUNT != '' }}
    steps:
      - uses: actions/checkout@v4
      - uses: actions/setup-python@v5
        with: { python-version: "3.12" }
      - run: pip install "snowflake-cli==3.*" "sqlglot>=25"
      - name: Static checks (every file parses; manifest order is complete)
        run: python scripts/check_manifest.py
      - name: EXPLAIN against target (dry run)
        if: env.HAS_SNOWFLAKE == 'true'
        env:
          SNOWFLAKE_ACCOUNT: ${{ secrets.SNOWFLAKE_ACCOUNT }}
          SNOWFLAKE_USER: ${{ secrets.SNOWFLAKE_USER }}
          SNOWFLAKE_PRIVATE_KEY_RAW: ${{ secrets.SNOWFLAKE_PRIVATE_KEY }}
          SNOWFLAKE_ROLE: ${{ vars.SNOWFLAKE_DEPLOY_ROLE }}
          SNOWFLAKE_WAREHOUSE: ${{ vars.SNOWFLAKE_WAREHOUSE }}
          SNOWFLAKE_DATABASE: ${{ vars.SNOWFLAKE_DATABASE }}
        run: bash scripts/deploy.sh --explain-only

  deploy:
    needs: validate
    if: github.ref == 'refs/heads/main'
    runs-on: ubuntu-latest
    environment: production          # requires approval in GitHub environments
    steps:
      - uses: actions/checkout@v4
      - uses: actions/setup-python@v5
        with: { python-version: "3.12" }
      - run: pip install "schemachange==4.*"
      - name: Deploy with schemachange (repeatable scripts in dependency order)
        env:
          SNOWFLAKE_ACCOUNT: ${{ secrets.SNOWFLAKE_ACCOUNT }}
          SNOWFLAKE_USER: ${{ secrets.SNOWFLAKE_USER }}
          SNOWFLAKE_PRIVATE_KEY_PATH: /tmp/key.p8
          SNOWFLAKE_ROLE: ${{ vars.SNOWFLAKE_DEPLOY_ROLE }}
          SNOWFLAKE_WAREHOUSE: ${{ vars.SNOWFLAKE_WAREHOUSE }}
          SNOWFLAKE_DATABASE: ${{ vars.SNOWFLAKE_DATABASE }}
        run: |
          printf '%s' "${{ secrets.SNOWFLAKE_PRIVATE_KEY }}" > /tmp/key.p8
          schemachange deploy --config-folder . --root-folder migrations
"""

SCHEMACHANGE = """config-version: 1
root-folder: migrations
change-history-table: SEMLIFT_META.CHANGE_HISTORY
create-change-history-table: true
snowflake-database: {database}
autocommit: false
"""

DEPLOY_SH = """#!/usr/bin/env bash
# Deploy approved SemanticLift objects with the Snowflake CLI, in manifest order.
#   scripts/deploy.sh               deploy
#   scripts/deploy.sh --explain-only run EXPLAIN on SELECT bodies only (dry run)
set -euo pipefail
cd "$(dirname "$0")/.."
MODE="${1:-deploy}"
DB="${SNOWFLAKE_DATABASE:?SNOWFLAKE_DATABASE must be set}"
python3 - "$MODE" "$DB" <<'PY'
import json, subprocess, sys, re
mode, db = sys.argv[1], sys.argv[2]
for item in json.load(open("manifest.json"))["objects"]:
    path = item["file"]
    if mode == "--explain-only":
        sql = open(path).read()
        m = re.search(r"\\bAS\\s*\\n(SELECT\\b.*?);", sql, re.S | re.I)
        if not m:
            continue
        cmd = ["snow", "sql", "--temporary-connection", "-q", f"USE DATABASE {db}; EXPLAIN USING TEXT {m.group(1)}"]
    else:
        cmd = ["snow", "sql", "--temporary-connection", "-q", f"USE DATABASE {db};", "-f", path]
    print("->", item["id"], flush=True)
    subprocess.run(cmd, check=True)
PY
"""

CHECK_MANIFEST = """#!/usr/bin/env python3
\"\"\"CI static check: manifest lists every migration once, dependencies are deployed first, SQL parses.\"\"\"
import json, os, re, sys
import sqlglot

m = json.load(open("manifest.json"))
files = sorted(os.listdir("migrations"))
listed = [os.path.basename(o["file"]) for o in m["objects"]]
errors = []
if sorted(listed) != files:
    errors.append("manifest and migrations/ differ")
seen = set()
ids = {o["id"] for o in m["objects"]}
for o in m["objects"]:
    for dep in o.get("depends_on", []):
        if dep in ids and dep not in seen:
            errors.append(f"{o['id']} deployed before dependency {dep}")
    seen.add(o["id"])
    sql = open(o["file"]).read()
    body = re.search(r"\\bAS\\s*\\n(SELECT\\b.*?);", sql, re.S | re.I)
    if body:
        try:
            sqlglot.parse_one(body.group(1), read="snowflake")
        except Exception as e:
            errors.append(f"{o['id']}: {e}")
print("\\n".join(errors) or f"OK: {len(m['objects'])} objects")
sys.exit(1 if errors else 0)
"""


def ci_files(database: str) -> dict[str, str]:
    return {
        ".github/workflows/semlift-deploy.yml": WORKFLOW,
        "schemachange-config.yml": SCHEMACHANGE.format(database=database),
        "scripts/deploy.sh": DEPLOY_SH,
        "scripts/check_manifest.py": CHECK_MANIFEST,
    }
